public sealed class PayrollService
{
    private readonly IClockEntryRepository _clockEntries;

    public PayrollService(IClockEntryRepository clockEntries)
    {
        _clockEntries = clockEntries;
    }

    public double CalculateTotalHours(int employeeId, DateTime startDate, DateTime endDate)
    {
        IEnumerable<ClockEntry> entries = _clockEntries.GetEmployeeClockEntries(employeeId, startDate, endDate);
        return entries.Sum(entry => entry.GetDuration().TotalHours);
    }
}

public static class ClockEntryQueries
{
    public static IEnumerable<ClockEntry> CompletedNewestFirst(IEnumerable<ClockEntry> entries) => entries
        .Where(entry => entry.Clockout is not null)
        .OrderByDescending(entry => entry.ClockIn);
}
